    69  static unsigned short int _ldecomp(const unsigned char *ptr)
    70  {
    71          unsigned short int i;
    72
    73          i = (unsigned short int)(0xc0 ^ ptr[0]);
    74          i = (unsigned short int)(i<<8);
    75          i = (unsigned short int)(i | ptr[1]);
    76
    77          return i;
    78  }
