    80  static bool _label(struct message *m, const unsigned char **bufp, const unsigned char *bufEnd, char **namep)
    81  {
    82          int x;
    83          const unsigned char *label;
    84          char *name;
    85
    86          /* Set namep to the end of the block */
    87          *namep = name = (char *)m->_packet + m->_len;
    88
    89          if (*bufp >= bufEnd)
    90              return false;
    91
    92      // forward buffer pointer until we find the first compressed label
    93      bool moveBufp = true;
    94          /* Loop storing label in the block */
    95          do {
    96              if (moveBufp) {
    97              label = *bufp;
    98              }
    99
   100          if (label >= bufEnd) {
   101              break;
   102          }
   103
   104          /* Since every domain name ends with the null label of
   105              the root, a domain name is terminated by a length byte of zero. */
   106          if (*label == 0) {
   107              if (moveBufp) {
   108                  *bufp += 1;
   109              }
   110              break;
   111          }
   112
   113
   114                  /* Skip past any compression pointers, kick out if end encountered (bad data prolly) */
   115
   116                  /* If a label is compressed, it has following structure of 2 bytes:
   117                   *    +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
   118           *    | 1  1|                OFFSET                   |
   119                   *    +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
   120                   *
   121                   * The OFFSET field specifies an offset from
   122                   * the start of the message (i.e., the first octet of the ID field in the
   123                   * domain header).  A zero offset specifies the first byte of the ID field,
   124                   * etc.
   125                   **/
   126                  if (*label & 0xc0) {
   127                      if (label + 2 > bufEnd)
   128                          return false;
   129              unsigned short int offset = _ldecomp(label);
   130              if (offset > m->_len)
   131                  return false;
   132              if (m->_buf + offset >= bufEnd)
   133                  return false;
   134              label = m->_buf + offset;
   135              // chek if label is again pointer, then abort.
   136              if (*label & 0xc0)
   137                  return false;
   138              moveBufp = false;
   139              *bufp += 2;
   140                  }
   141
   142
   143                  /* Make sure we're not over the limits
   144                   * See https://tools.ietf.org/html/rfc1035
   145                   * 2.3.4. Size limits
   146                   * */
   147                  const unsigned char labelLen = (unsigned char)*label;
   148                  if (labelLen > 63)
   149                      // maximum label length is 63 octets
   150                      return false;
   151                  long nameLen = (name + labelLen) - *namep;
   152                  if (nameLen > 255)
   153              // maximum names length is 255 octets
   154                      return false;
   155
   156                  if (label + 1 + labelLen > bufEnd) {
   157              return false;
   158          }
   159          if ((unsigned char*)name + labelLen > m->_packet + MAX_PACKET_LEN) {
   160              return false;
   161          }
   162                  /* Copy chars for this label */
   163                  memcpy(name, label + 1, labelLen);
   164                  name[labelLen] = '.';
   165
   166          name += labelLen + 1;
   167
   168          if (moveBufp) {
   169              *bufp += labelLen + 1;
   170          }
   171          else {
   172              label += labelLen +1;
   173          }
   174
   175          } while (*bufp <= bufEnd);
   176
   177          /* Terminate name and check for cache or cache it */
   178          *name = '\0';
   179          for (x = 0; x < MAX_NUM_LABELS && m->_labels[x]; x++) {
   180                  if (strcmp(*namep, m->_labels[x]))
   181                          continue;
   182
   183                  *namep = m->_labels[x];
   184                  return true;
   185          }
   186
   187          /* No cache, so cache it if room */
   188          if (x < MAX_NUM_LABELS && m->_labels[x] == 0) {
   189          m->_labels[x] = *namep;
   190      }
   191      m->_len += (unsigned long)((name - *namep) + 1);
   192
   193          return true;
   194  }
