   231  /* Nasty, convert host into label using compression */
   232  static int _host(struct message *m, unsigned char **bufp, char *name)
   233  {
   234          char label[256], *l;
   235          int len = 0, x = 1, y = 0, last = 0;
   236
   237          if (name == 0)
   238                  return 0;
   239
   240          /* Make our label */
   241          while (name[y]) {
   242                  if (name[y] == '.') {
   243                          if (!name[y + 1])
   244                                  break;
   245                          label[last] = (char)(x - (last + 1));
   246                          last = x;
   247                  } else {
   248                          label[x] = name[y];
   249                  }
   250
   251                  if (x++ == 255)
   252                          return 0;
   253
   254                  y++;
   255          }
   256
   257          label[last] = (char)(x - (last + 1));
   258          if (x == 1)
   259                  x--;            /* Special case, bad names, but handle correctly */
   260          len = x + 1;
