    36  extern "C" int
    37  LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    38
    39
    40      struct message m;
    41      memset(&m, 0, sizeof(struct message));
    42
    43      unsigned char *dataCopy = (unsigned char *)malloc(size);
    44      if (!dataCopy) {
    45          return 0;
    46      }
    47
    48      memcpy(dataCopy, data, size);
    49
    50      bool success = message_parse(&m, dataCopy, size);
    51
    52      free(dataCopy);
    53
    54      if (!success)
    55          return 0;
    56
    57      mdns_daemon_t *d = mdnsd_new(QCLASS_IN, 1000);
    58
    59      in_addr_t addr = 0;
    60      mdnsd_in(d, &m, addr, 2000);
    61
    62      mdnsd_free(d);
    63
    64      return 0;
    65  }
